def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if not alive:
        return float(min(budget, DAILY_SALARY * 0.22))

    opp_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) >= DAILY_SALARY * 2:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            opp_bids.append(prev.get('bid', 0))

    highest_prev = max(opp_bids) if opp_bids else 0.0
    avg_prev = sum(opp_bids) / len(opp_bids) if opp_bids else 0.0

    scarcity = 1.0
    if supply <= 16:
        scarcity = 1.25
    elif supply >= 23:
        scarcity = 0.85

    danger = 0
    if hp <= 2:
        danger += 3
    elif hp <= 4:
        danger += 2
    elif hp <= 6:
        danger += 1

    if no_water >= 2:
        danger += 3
    elif no_water >= 1:
        danger += 2

    if day >= 8:
        danger += 1

    if danger >= 5:
        target = max(DAILY_SALARY * 1.05, highest_prev + 6.0, avg_prev + 10.0)
    elif danger >= 3:
        target = max(DAILY_SALARY * 0.72, highest_prev * 0.72 + 3.0, avg_prev + 2.0)
    else:
        if highest_prev >= 140:
            target = DAILY_SALARY * 0.24
        elif highest_prev >= 110:
            target = DAILY_SALARY * 0.30
        elif highest_prev >= 80:
            target = DAILY_SALARY * 0.42
        else:
            target = DAILY_SALARY * 0.52

    if urgent_opp >= 2:
        target += 6.0
    elif urgent_opp == 1:
        target += 3.0

    if rich_opp >= 2 and danger <= 2:
        target -= 4.0

    target *= scarcity

    if budget < DAILY_SALARY * 1.2 and danger <= 2:
        target = min(target, DAILY_SALARY * 0.38)

    if hp >= 8 and no_water == 0 and supply >= 22 and highest_prev >= 100:
        target = min(target, DAILY_SALARY * 0.22)

    bid = max(0.0, min(float(budget), float(target)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10 

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1) 

    my_base_bid = DAILY_SALARY * 0.85 

    if my_status['no_water_days'] > 0:
        my_base_bid = DAILY_SALARY * 1.15
    elif my_status['hp'] <= 2:
        my_base_bid = DAILY_SALARY * 1.25
    elif my_status['hp'] <= 4:
        my_base_bid = DAILY_SALARY * 1.05
    elif my_status['hp'] >= 8:
        my_base_bid = DAILY_SALARY * 0.75

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= DAILY_SALARY * 1.0:
            if my_status['hp'] <= 4 or my_status['no_water_days'] > 0:
                my_base_bid = max(my_base_bid, highest_prev_bid + 5)
            else:
                my_base_bid = max(my_base_bid, highest_prev_bid * 0.95)

        elif highest_prev_bid >= DAILY_SALARY * 0.7:
            my_base_bid = max(my_base_bid, highest_prev_bid + 2)
            if my_status['hp'] >= 8:
                my_base_bid = min(my_base_bid, DAILY_SALARY * 0.9)

        else:
            if my_status['hp'] > 4 and my_status['no_water_days'] == 0:
                my_base_bid = min(my_base_bid, highest_prev_bid + 1)
            else:
                my_base_bid = max(my_base_bid, highest_prev_bid + 5)

    water_units_available = day_context['supply']
    num_total_competitors = len(alive_opponents) + 1
    max_people_to_satisfy_fully = int(water_units_available / WATER_REQ)

    if num_total_competitors > max_people_to_satisfy_fully:
        if my_status['hp'] <= 4 or my_status['no_water_days'] > 0:
            my_base_bid *= 1.05
        else:
            my_base_bid *= 1.02
    elif num_total_competitors <= max_people_to_satisfy_fully and num_total_competitors > 0:
        if my_status['hp'] >= 8 and my_status['no_water_days'] == 0:
            my_base_bid *= 0.95
        else:
            my_base_bid *= 0.98

    final_bid = min(my_base_bid, my_status['budget'])
    final_bid = max(1, final_bid)

    return final_bid
